    murphy2022: { a: 'Murphy C, Koehler K', y: 2022, t: 'Energy deficiency impairs resistance training gains in lean mass but not strength: a meta-analysis and meta-regression', j: 'Scand J Med Sci Sports 32(1):125–137', u: 'https://doi.org/10.1111/sms.14075', k: 'metaanaliza' },
    iraki2019: { a: 'Iraki J, Fitschen P, Espinar S, Helms E', y: 2019, t: 'Nutrition recommendations for bodybuilders in the off-season: a narrative review', j: 'Sports 7(7):154', u: 'https://doi.org/10.3390/sports7070154', k: 'przegląd narracyjny' },
    wilson2012: { a: 'Wilson JM, Marin PJ, Rhea MR, Wilson SM, Loenneke JP, Anderson JC', y: 2012, t: 'Concurrent training: a meta-analysis examining interference of aerobic and resistance exercises', j: 'J Strength Cond Res 26(8):2293–2307', u: 'https://doi.org/10.1519/JSC.0b013e31823a3e2d', k: 'metaanaliza' },
    schumann2022: { a: 'Schumann M, Feuerbacher JF, Sünkeler M i in.', y: 2022, t: 'Compatibility of concurrent aerobic and strength training for skeletal muscle size and function: an updated systematic review and meta-analysis', j: 'Sports Med 52(3):601–612', u: 'https://doi.org/10.1007/s40279-021-01587-7', k: 'metaanaliza (43 badania)' },
    sawka2007: { a: 'American College of Sports Medicine; Sawka MN, Burke LM, Eichner ER i in.', y: 2007, t: 'American College of Sports Medicine position stand. Exercise and fluid replacement', j: 'Med Sci Sports Exerc 39(2):377–390', u: 'https://doi.org/10.1249/mss.0b013e31802ca597', k: 'stanowisko towarzystwa (ACSM)' },
    herrmann2024: { a: 'Herrmann SD, Willis EA, Ainsworth BE i in.', y: 2024, t: '2024 Adult Compendium of Physical Activities: a third update of the energy costs of human activities', j: 'J Sport Health Sci 13(1):6–12', u: 'https://pacompendium.com/conditioning-exercise', k: 'kompendium wartości MET' },
    morannavarro2017: { a: 'Morán-Navarro R, Pérez CE, Mora-Rodríguez R i in.', y: 2017, t: 'Time course of recovery following resistance training leading or not to failure', j: 'Eur J Appl Physiol 117(12):2387–2399', u: 'https://doi.org/10.1007/s00421-017-3725-7', k: 'badanie eksperymentalne' },
    travis2020: { a: 'Travis SK, Mujika I, Gentles JA, Stone MH, Bazyler CD', y: 2020, t: 'Tapering and peaking maximal strength for powerlifting performance: a review', j: 'Sports (Basel) 8(9):125', u: 'https://doi.org/10.3390/sports8090125', k: 'przegląd' },
    travis2021: { a: 'Travis SK, Pritchard HJ, Mujika I, Gentles JA, Stone MH, Bazyler CD', y: 2021, t: 'Characterizing the tapering practices of United States and Canadian raw powerlifters', j: 'J Strength Cond Res 35(Suppl 2):S26–S35', u: 'https://doi.org/10.1519/JSC.0000000000004177', k: 'badanie ankietowe' },
    burke2023: { a: 'Burke BI, Carroll KM, Travis SK, Stone ME, Stone MH', y: 2023, t: 'Two days versus four days of training cessation following a step-taper in powerlifters', j: 'J Strength Cond Res 37(12):625–632', u: 'https://doi.org/10.1519/JSC.0000000000004564', k: 'badanie' },
    winwood2026: { a: 'Winwood PW, Travis SK, Barnes MJ, Keogh JWL, Pritchard HJ', y: 2026, t: 'Tapering and peaking in the weight lifting sports: a systematic review of athletes\' self-reported strategies', j: 'Sports Med 56(12):3099–3123', u: 'https://doi.org/10.1007/s40279-026-02500-w', k: 'przegląd systematyczny' },
